function HomelandCheckInUpgradeGroup:CleanProperties()
    self.comp = nil
    self.groupId = nil
    self.FontStyleButton = nil
end

function HomelandCheckInUpgradeGroup:Refresh(groupId)
    self.groupId = groupId

    local groupVo = self.comp:GetGroupVo(groupId)
    if isNull(groupVo) then
        return
    end

    -- 队伍名称
    CfUtils.FillText(self.TxtTeamName, groupVo.name)

    local level = self.comp:GetGroupLevel(groupId)
    local levelMax = self.comp:GetGroupUpgradeLevelMax(groupId)
    local isMax = level >= levelMax

    KTool.SetActive(self.MaxGroup, isMax)
    KTool.SetActive(self.UpgradesGroup, not isMax)

    -- 属性组
    local totalAttr1 = self.comp:GetGroupTotalUpgradeAttr(groupId, level)
    local totalAttr2 = self.comp:GetGroupTotalUpgradeAttr(groupId, level + 1)
    local activeInfo = self.comp:GetCheckInActiveInfo(groupId)
    local multi1 = 0
    if activeInfo.index1 > 0 then
        multi1 = activeInfo.vo1.attrNums[1]  -- 模块1的加成
    end
    local multi2 = 1
    if activeInfo.index2 > 0 then
        multi2 = activeInfo.vo2.attrNums[1]  -- 模块2的加成
    end

    local addPower = 0
    local data = {}
    for color, attrs in pairs(totalAttr1) do
        for attrId, num in pairs(attrs) do
            local num1 = math.floor(num * multi1 * multi2)
            local num2 = math.floor(totalAttr2[color][attrId] * multi1 * multi2)
            addPower = addPower + self:CalculatePower(attrId, (num2 - num1))    -- 记录累计增加的战力
            local hasUpgrade = num2 > num1
            if isMax then
                num2 = nil
            end
            table.insert(data, {attrAddId = attrId, color = color, num = num1, num2 = num2, hasUpgrade = hasUpgrade})
        end
    end

    table.sort(data, function(a,b)
        return a.attrAddId < b.attrAddId
    end)

    local lb = GetLuaBehaviour(self.StatsNode.gameObject, AttrNodeLuaPath)
    if isNotNull(lb) then
        lb.Env:Refresh(data)
    end
    
    -- 等级组
    CfUtils.FillText(self.TxtNumber1, string.format("<size=46>lv.</size>%d", level))
    CfUtils.FillText(self.TxtNumber2, string.format("<size=46>lv.</size>%d", level + 1))

    -- 道具组
    local upgradeVo = self.comp:GetGroupUpgradeVoByLevel(groupId, level + 1)
    if isNotNull(upgradeVo) then
        local consumes = upgradeVo.costItems
        ---@type CommonGoodsListLight
        local scr = CfUtils.GetLuaScr(self.CommonGoodsListLight, CommonGoodsListLightLuaPath)
        scr:FreshBaseUI(consumes, false, false, true, true, true)

        -- 升级按钮
        local enough = GoodsUtils.CheckGoodConsumeCondition(consumes)
        self.FontStyleButton:ResetFontStyle(enough and "B1" or "B17")
        SetButtonAction(self.FontStyleButton.gameObject, function()
            if enough then
                self.comp:RequestUpgrade(groupId, consumes, function()
                    -- 战力增加的飘字
                    if checkNumber(addPower) > 0 then
                        CardProgressionUtils.ChangePointToast(addPower)
                    end
                    -- 升级时播放特效
                    self:PlayUpgradeUIFX(lb, data)
                end)
            else
                GameUtils.Toast(localize("道具不足"))
            end
        end)
    end
end

--- 计算战力增加
---@param attrAddId any
---@param addNum any
function HomelandCheckInUpgradeGroup:CalculatePower(attrAddId, addNum)
    local vo = CardConfMgr:GetInstance():GetBasicAttrByBasicAttrAdditionId(attrAddId)
    local power = vo.combatEff * addNum
    return power
end

function HomelandCheckInUpgradeGroup:PlayUpgradeUIFX(lb, data)
    for i, d in ipairs(data) do
        if d.hasUpgrade then
            lb.Env:PlayUpgradeUIFX(i)
        end
    end
end

return HomelandCheckInUpgradeGroup